package com.tripnest.dto;
import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*;
public final class ApiDtos { private ApiDtos(){} public record Register(@NotBlank @Size(max=100) String fullName,@Email @NotBlank String email,@NotBlank @Size(min=8,max=72) String password){} public record Login(@Email @NotBlank String email,@NotBlank String password){} public record Auth(String token,UserView user){} public record UserView(Long id,String fullName,String email,String role){} public record BookingRequest(@NotNull @Future LocalDate checkIn,@NotNull @Future LocalDate checkOut,@Min(1) int guests){} public record BookingView(String reference,String accommodation,Long accommodationId,LocalDate checkIn,LocalDate checkOut,int guests,int nights,BigDecimal pricePerNight,BigDecimal taxAmount,BigDecimal totalAmount,String status){} public record Contact(@NotBlank String name,@Email @NotBlank String email,@NotBlank String subject,@NotBlank String message){} public record AccommodationView(Long id,String name,String type,String city,String country,String address,String shortDescription,String description,BigDecimal pricePerNight,int maxGuests,BigDecimal rating,List<String> images,List<String> amenities,boolean active){} public record AccommodationRequest(@NotBlank String name,@NotBlank String type,@NotBlank String city,@NotBlank String country,@NotBlank String address,@NotBlank String shortDescription,@NotBlank String description,@NotNull @DecimalMin("0.01") BigDecimal pricePerNight,@Min(1) int maxGuests,@DecimalMin("0.0") @DecimalMax("5.0") BigDecimal rating,List<String> images,List<String> amenities){} public record StatusRequest(@NotNull com.tripnest.entity.BookingStatus status){} }
